let LECTURE_CONTENT=null, CONTENT_LOADING=null;
function lectureContent(){
  if(LECTURE_CONTENT)return Promise.resolve(LECTURE_CONTENT);
  if(!CONTENT_LOADING){
    const url='content/lecture-content.json';
    const load=typeof fetch==='function'
      ? fetch(url,{cache:'force-cache'}).then(r=>{if(!r.ok)throw new Error('HTTP '+r.status);return r.json();})
      /* بيئات بلا fetch (اختبارات/متصفحات قديمة) — نفس الملف عبر XHR */
      : new Promise((res,rej)=>{const x=new XMLHttpRequest();x.open('GET',url,true);
          x.onload=()=>{if(x.status>=200&&x.status<300){try{res(JSON.parse(x.responseText));}catch(e){rej(e);}}else rej(new Error('HTTP '+x.status));};
          x.onerror=()=>rej(new Error('network'));x.send();});
    CONTENT_LOADING=load
      .then(j=>{LECTURE_CONTENT=j;return j;})
      .catch(err=>{CONTENT_LOADING=null;throw err;});
  }
  return CONTENT_LOADING;
}
