async function detail(id,refresh=false){if(!refresh&&S.detailCache.has(id))return S.detailCache.get(id);const d=await api('/api/subjects/'+encodeURIComponent(id));S.data.files=[...((S.data.files||[]).filter(f=>f.subject_id!==id)),...d.files];S.detailCache.set(id,d);return d;}
