function empty(title,desc,icon='book',action=''){return `<div class="empty"><div class="empty-icon">${i(icon)}</div><h3>${h(title)}</h3><p>${h(desc)}</p>${action}</div>`;}
function heading(title,subtitle='',action=''){return `<div class="page-heading"><div><h1>${h(title)}</h1>${subtitle?`<p>${h(subtitle)}</p>`:''}</div>${action}</div>`;}
function progressOf(sid){const ls=S.data.lectures.filter(l=>l.subject_id===sid&&l.kind!=='assignment');const done=ls.filter(l=>S.local.completed.includes(l.id)).length;return {done,total:ls.length,percent:ls.length?Math.round(done/ls.length*100):0};}
function progressBar(sid){const p=progressOf(sid);return `<div class="subject-progress"><div class="between"><span>${t('تقدّمك في المادة','Your progress')}</span><span>${fmt(p.percent)}%</span></div><div class="progress-track"><div class="progress-fill" style="width:${p.percent}%"></div></div></div>`;}
