function fileTitle(f){
 const src=sourceOf(f.id);
 if(S.lang==='en')return (src?.title_en||f.title_en||f.original_name||f.title||'').trim();
 return (src?.title_ar||f.title||src?.title_en||f.original_name||'').trim();
}
function cardsFor(l){const groups=Array.isArray(l?.content?.cards)?l.content.cards:[];if(!englishMaterial(l?.subject_id))return groups[0]||[];const ar=v=>/[\u0600-\u06FF]/.test(JSON.stringify(v)),out=[],seen=new Set();for(const g of groups)if(Array.isArray(g)&&g.length&&g.every(v=>!ar(v)))for(const v of g){const k=JSON.stringify(v);if(!seen.has(k)){seen.add(k);out.push(v);}}for(const g of groups)if(Array.isArray(g))for(const v of g)if(!ar(v)){const k=JSON.stringify(v);if(!seen.has(k)){seen.add(k);out.push(v);}}return out;}
function subjectNote(sid){const n=(S.data.sources&&S.data.sources.subjects&&S.data.sources.subjects[sid])||null;return n?(englishMaterial(sid)?n.note_en||n.note_ar||'':n.note_ar||n.note_en||''):'';}
function srcTitle(src){return src?field(src,'title'):'';}
function noteOf(src){return src?field(src,'note'):'';}
function coverageOf(sid){
 const rows=S.data.lectures.filter(l=>l.subject_id===sid&&l.kind!=='assignment');
 const labs=rows.filter(l=>l.kind==='lab').length;
 const assignments=S.data.lectures.filter(l=>l.subject_id===sid&&l.kind==='assignment').length;
 const files=(S.data.files||[]).filter(f=>f.subject_id===sid);
 const questions=S.data.questions?S.data.questions.filter(q=>q.subject_id===sid).length:(S.data.subjects.find(s=>s.id===sid)?.question_count||0);
 const subject=S.data.subjects.find(s=>s.id===sid)||{};
 return {lectures:rows.length-labs,labs,assignments,files:files.length,
   questions:S.data.questions?S.data.questions.filter(q=>q.subject_id===sid).length:(subject.question_count||0),
   sourceFiles:files.filter(f=>sourceOf(f.id)).length,
   hasSource:files.length>0};
}
function coverageRows(){return S.data.subjects.map(s=>({s,c:coverageOf(s.id)}));}
