 <section class="card pad"><div class="between wrap"><h2>${t('جدول التغطية','Coverage table')}</h2><span class="tiny muted">${t('محاضرات / تجارب / تكليفات / ملفات / أسئلة','lectures / labs / assignments / files / questions')}</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>${t('المادة','Subject')}</th><th>${t('الفصل','Sem.')}</th><th>${t('محاضرات','Lectures')}</th><th>${t('تجارب','Labs')}</th><th>${t('تكليفات','Assignments')}</th><th>${t('ملفات','Files')}</th><th>${t('صفحات','Pages')}</th><th>${t('أسئلة','Questions')}</th><th>${t('ملاحظة','Note')}</th></tr></thead><tbody>${rows.map(({s,c})=>{const pages=(S.data.files||[]).filter(f=>f.subject_id===s.id).reduce((n,f)=>n+(sourceOf(f.id)?.pages||0),0);const note=subjectNote(s.id);return `<tr><td><a href="#/subject/${h(s.id)}"><strong>${h(s.code)}</strong></a><br><span class="tiny muted">${h(field(s,'name'))}</span></td><td>${s.semester?fmt(s.semester):t('إضافية','Extra')}</td><td>${fmt(c.lectures)}</td><td>${fmt(c.labs)}</td><td>${fmt(c.assignments)}</td><td>${fmt(c.files)}</td><td>${pages?fmt(pages):'—'}</td><td>${fmt(c.questions)}</td><td class="tiny ${c.hasSource?'':'muted'}">${note?h(note):'—'}</td></tr>`;}).join('')}</tbody></table></div></section>
