document.addEventListener('input',e=>{if(e.target&&e.target.id==='fsSearch'){S.fsQuery=e.target.value;fsApply();}});
document.addEventListener('submit',async e=>{
 const form=e.target;e.preventDefault();const button=form.querySelector('[type=submit]');if(button?.disabled)return;const old=button?.innerHTML;if(button){button.disabled=true;button.innerHTML=i('refresh','spin')+' '+t('جارٍ الحفظ…','Saving…');}
 try{
 if(form.id==='student-login-form'||form.id==='register-form'){const fd=new FormData(form),register=form.id==='register-form';const payload=Object.fromEntries(fd.entries());if(register){payload.semester=Number(payload.semester);payload.consent=fd.has('consent');}const d=await api(register?'/api/student/register':'/api/student/login',{method:'POST',body:JSON.stringify(payload)});if(!register&&!d.user.must_change){const p=await api('/api/student/progress',{headers:{'X-Method-CSRF':d.csrf}});Object.assign(d,p);}accountApplied(d);toast(t('أهلًا بك في مساحتك الدراسية.','Welcome to your study space.'));if(register&&d.recovery_code)setTimeout(()=>showRecovery(d.recovery_code),250);return;}
 if(form.id==='practice-form'){await startPractice(form);return;}
 if(form.id==='ai-form'){await sendAI();return;} if(form.id==='recover-form'){await recoverAccount(form);return;}
 if(form.id==='task-form'){if(S.local.tasks.length>=200)throw new Error(t('الحد الأقصى 200 مهمة. احذف المهام القديمة أولًا.','Maximum 200 tasks. Remove old tasks first.'));const fd=new FormData(form);S.local.tasks.push({id:uid(),title:String(fd.get('title')).trim().slice(0,200),subject:String(fd.get('subject')),date:String(fd.get('date')),done:false});persist();closeDialog();await render();toast(t('أُضيفت الخطوة إلى خطتك.','Step added to your plan.'));return;}
 if(form.id==='progress-import-form'){const file=new FormData(form).get('file');if(file.size>5*1024*1024)throw new Error(t('الحد الأقصى لملف التقدّم 5 MB.','Maximum progress file size is 5 MB.'));let payload;try{payload=JSON.parse(await file.text());}catch{throw new Error(t('ملف JSON غير صالح.','Invalid JSON file.'));}if(payload.format!=='method-student-progress'||payload.version!==1||!payload.data||typeof payload.data!=='object')throw new Error(t('هذا ليس ملف تقدم ENG YOUSSEF مدعومًا.','This is not a supported progress file.'));const x=validateLocal(payload.data);S.local.completed=[...new Set([...S.local.completed,...x.completed])];S.local.savedLectures=[...new Set([...S.local.savedLectures,...x.savedLectures])];S.local.savedQuestions=[...new Set([...S.local.savedQuestions,...x.savedQuestions])];S.local.recent=[...new Set([...x.recent,...S.local.recent])].slice(0,15);S.local.notes={...S.local.notes,...x.notes};const tasks=new Map(S.local.tasks.map(t=>[t.id,t]));x.tasks.forEach(t=>tasks.set(t.id,t));S.local.tasks=[...tasks.values()].slice(0,200);const attempts=new Map(S.local.attempts.map(a=>[a.id,a]));x.attempts.forEach(a=>attempts.set(a.id,a));S.local.attempts=[...attempts.values()].sort((a,b)=>b.date-a.date).slice(0,30);persist();closeDialog();await render();toast(t('تم استيراد تقدمك ودمجه بأمان.','Progress imported and merged.'));return;}
 }catch(err){toast(err.message,'error');}finally{if(button?.isConnected){button.disabled=false;button.innerHTML=old;}}
});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchDialog();}if(S.quiz&&!S.quiz.finished&&S.route==='practice'&&!$('dialog')&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)){if(e.key==='ArrowLeft'){e.preventDefault();S.quiz.index=Math.min(S.quiz.questions.length-1,S.quiz.index+(S.lang==='ar'?1:-1));saveQuiz();render();}if(e.key==='ArrowRight'){e.preventDefault();S.quiz.index=Math.max(0,S.quiz.index+(S.lang==='ar'?-1:1));saveQuiz();render();}}});
window.addEventListener('hashchange',()=>{if(S.local.notes)persist();render();});
window.addEventListener('pagehide',()=>{persist();saveQuiz();});
setInterval(()=>{if(S.quiz&&!S.quiz.finished&&S.quiz.deadline){const left=Math.max(0,(S.quiz.deadline-Date.now())/1000),el=$('#quiz-timer');if(el){el.textContent=duration(left);el.classList.toggle('urgent',left<60);}if(left<=0){toast(t('انتهى الوقت. نحفظ إجاباتك للمراجعة.','Time is up. Saving your answers for review.'));finishQuiz(true);}}},1000);
/* Personal identity, fixed Arabic invocation, university sources and real student accounts. */
const QURAN='رَبِّ اشْرَحْ لِي صَدْرِي* وَيَسِّرْ لِي أَمْرِي* وَاحْلُلْ عُقْدَةً مِّن لِّسَانِي* يَفْقَهُوا قَوْلِ';
function quranBanner(){return `<section class="quran-banner"><span class="quran-mark" aria-hidden="true">۞</span><div><span class="quran-label">${t('بداية طمأنينة وتوفيق','A moment of intention')}</span><blockquote lang="ar" dir="rtl">${QURAN}</blockquote></div><span class="quran-end" aria-hidden="true">۞</span></section>`;}
function semesterSubjects(n){return S.data.subjects.filter(s=>s.semester===n);}
function syncLabel(){return S.student?({synced:t('مزامنة مع حسابك','Synced to your account'),pending:t('جارٍ المزامنة…','Syncing…'),conflict:t('نسخة أحدث على الخادم','Newer server copy'),error:t('المزامنة غير مكتملة','Sync incomplete')}[S.syncState]||t('حساب طالب','Student account')):t('تقدّمك محفوظ على هذا المتصفح','Progress saved in this browser');}
function updateSyncBadge(){const el=$('#sync-status');if(el)el.textContent=syncLabel();}
let syncTimer,syncRunning=false,syncAgain=false;
function queueSync(){updateSyncBadge();if(!S.student||OFFLINE||S.student.must_change||S.syncState==='conflict')return;clearTimeout(syncTimer);S.syncState='pending';updateSyncBadge();syncTimer=setTimeout(()=>syncProgress().catch(()=>{}),700);}
async function syncProgress(){if(!S.student||OFFLINE||S.student.must_change||S.syncState==='conflict')return;if(syncRunning){syncAgain=true;return;}syncRunning=true;try{do{syncAgain=false;const snapshot=JSON.stringify(S.local),revision=S.studentRevision;const r=await api('/api/student/progress',{method:'PUT',body:JSON.stringify({revision,data:JSON.parse(snapshot)})});S.studentRevision=r.revision;S.syncState='synced';if(JSON.stringify(S.local)!==snapshot)syncAgain=true;}while(syncAgain&&S.syncState!=='conflict');}catch(e){S.syncState=e.status===409?'conflict':'error';}finally{syncRunning=false;updateSyncBadge();}}
async function loadStudentProgress(){const r=await api('/api/student/progress');S.studentRevision=r.revision;S.local=r.data?validateLocal(r.data):emptyLocal();S.local.lang=S.lang;S.local.theme=S.theme;S.syncState='synced';try{localStorage.setItem(storageKey(),JSON.stringify(S.local));}catch{}updateSyncBadge();}
function accountApplied(d){S.student=d.user;S.studentCsrf=d.csrf;S.studentRevision=d.revision||0;S.quiz=null;S.lastResult=null;saveQuiz();S.local=d.data?validateLocal(d.data):emptyLocal();S.local.lang=S.lang;S.local.theme=S.theme;S.syncState='synced';S.admin=false;S.mustChange=false;invalidate();try{localStorage.setItem(storageKey(),JSON.stringify(S.local));}catch{}shell();navigate('#/account');}
async function studentLogout(){clearTimeout(syncTimer);await syncProgress();if(S.syncState==='conflict')throw new Error(t('حمّل نسخة الخادم أو صدّر تقدمك قبل الخروج؛ توجد تغييرات لم تُزامن.','Load the server copy or export your progress before signing out; unsynced changes exist.'));await api('/api/student/logout',{method:'POST'});S.student=null;S.studentCsrf='';S.local=loadLocal();S.syncState='guest';S.quiz=null;S.lastResult=null;saveQuiz();invalidate();shell();navigate('#/');toast(t('تم تسجيل الخروج بأمان.','Signed out securely.'));}
function loginPage(register=false){
 if(S.student)return accountPage();
 return `<div class="auth-layout"><section class="auth-story"><div class="auth-brand"><img src="assets/brand-mark.jpg" alt="ENG YOUSSEF" width="56" height="56"><span>ENG YOUSSEF</span></div><div class="eyebrow en">ENG YOUSSEF · STUDENT SPACE</div><h1>${t('خطوتك القادمة،<br>تبدأ من هنا.','Your next step<br>starts here.')}</h1><p>${t('حسابك الدراسي الخاص: موادك، تدريبك، ملاحظاتك وتقدمك محفوظ ومزامن مع الخادم.','Your personal study account: subjects, practice, notes and progress saved and synced to the server.')}</p>${quranBanner()}<ul class="security-list"><li>${t('بنك أسئلة مستقل لكل مادة','A dedicated question bank for each subject')}</li><li>${t('الفصل الأول والثاني في مكان واحد','Semester 1 and 2 in one place')}</li><li>${t('روابط رسمية للجامعة وLMS','Official university and LMS links')}</li></ul><small>${t('منصة شخصية مستقلة، وليست حسابًا جامعيًا أو بديلًا عن LMS.','An independent personal platform, not a university account or an LMS replacement.')}</small></section><section class="card auth-card"><div class="auth-tabs"><a class="tab ${!register?'active':''}" href="#/login">${t('تسجيل الدخول','Sign in')}</a><a class="tab ${register?'active':''}" href="#/register">${t('حساب جديد','Create account')}</a></div><h2>${register?t('أنشئ مساحتك الدراسية','Create your study space'):t('أهلًا بعودتك','Welcome back')}</h2><p class="small">${register?t('استخدم كلمة مرور فريدة لهذا الموقع. لا تستخدم كلمة مرور الجامعة.','Use a unique password for this site. Never reuse your university password.'):t('ادخل ببيانات حساب ENG YOUSSEF، وليس بيانات LMS الجامعي.','Use your ENG YOUSSEF account, not your university LMS credentials.')}</p>${OFFLINE?`<div class="info-box warning">${t('الحسابات الحقيقية تحتاج نسخة الخادم المرفقة. النسخة المستقلة تتيح الدراسة دون حساب.','Real accounts require the included server. The standalone edition supports studying without an account.')}</div>`:`<form id="${register?'register-form':'student-login-form'}">${register?`<div class="field"><label for="r-name">${t('الاسم','Full name')}</label><input id="r-name" name="name" autocomplete="name" minlength="2" maxlength="100" required></div><div class="field"><label for="r-email">${t('البريد الإلكتروني','Email')}</label><input id="r-email" name="email" type="email" autocomplete="email" maxlength="254" dir="ltr" required></div>`:''}<div class="field"><label for="s-username">${register?t('اسم المستخدم','Username'):t('اسم المستخدم أو البريد','Username or email')}</label><input id="s-username" name="username" autocomplete="username" maxlength="${register?40:254}" ${register?'pattern="[A-Za-z0-9_.\\-]{3,40}"':''} dir="ltr" required></div><div class="field"><label for="s-password">${t('كلمة المرور','Password')}</label><input id="s-password" name="password" type="password" autocomplete="${register?'new-password':'current-password'}" minlength="${register?12:1}" maxlength="256" dir="ltr" required>${register?`<small class="muted">${t('12 حرفًا على الأقل، ويفضل عبارة طويلة فريدة.','At least 12 characters; a long unique passphrase is recommended.')}</small>`:''}</div>${register?`<div class="form-grid"><div class="field"><label for="r-semester">${t('الفصل الدراسي','Semester')}</label><select id="r-semester" name="semester"><option value="1">${t('الفصل الأول','Semester 1')}</option><option value="2">${t('الفصل الثاني','Semester 2')}</option><option value="0">${t('غير محدد','Not specified')}</option></select></div><div class="field"><label for="r-program">${t('البرنامج','Program')}</label><select id="r-program" name="program"><option value="mechatronics">${t('الميكاترونكس','Mechatronics')}</option><option value="energy">${t('هندسة الطاقة','Energy Engineering')}</option><option value="other">${t('برنامج آخر','Other program')}</option></select></div></div><label class="check mb"><input type="checkbox" name="consent" required>${t('أوافق على حفظ اسمي وبريدي وتقدمي الدراسي على خادم هذا الموقع لتقديم الخدمة. أفهم أن المنصة مستقلة عن الجامعة.','I agree to storage of my name, email and study progress on this site’s server to provide the service. I understand it is independent of the university.')}</label>`:''}<button type="submit" class="btn primary full">${i('lock')}${register?t('إنشاء الحساب','Create account'):t('دخول إلى مساحتي','Sign in to my space')}</button></form>${!register?`<a class="text-link mt" href="#/recover">${t('نسيت كلمة المرور؟ استخدم رمز الاستعادة','Forgot your password? Use your recovery code')}</a>`:''}`}<a class="text-link mt" href="#/">${t('متابعة التصفح بدون تسجيل الدخول','Continue browsing without signing in')}${i('arrow')}</a><div class="divider"></div></section></div>${footer()}`;
}
function accountPage(){if(!S.student)return loginPage();const u=S.student;return `${heading(t('حسابي الدراسي','My student account'),t('تقدمك مرتبط بحسابك، وليس ببيانات دخول الجامعة.','Progress belongs to your account, not your university credentials.'),`<button class="btn" data-action="student-logout">${i('logout')}${t('خروج','Sign out')}</button>`)}${u.must_change?`<section class="card pad mb"><h2>${t('غيّر كلمة المرور المؤقتة','Change your temporary password')}</h2>${passwordForm('student-password-form')}</section>`:''}<div class="settings-grid"><section class="card pad"><div class="flex mb"><div class="avatar large">${h(u.name.slice(0,1))}</div><div><h2 class="no-margin">${h(u.name)}</h2><p class="en muted">@${h(u.username)}</p></div></div><dl class="account-details"><dt>${t('البريد','Email')}</dt><dd class="en">${h(u.email)}</dd><dt>${t('الفصل','Semester')}</dt><dd>${u.semester?fmt(u.semester):t('غير محدد','Not specified')}</dd><dt>${t('البرنامج','Program')}</dt><dd>${h({mechatronics:t('الميكاترونكس','Mechatronics'),energy:t('هندسة الطاقة','Energy Engineering'),other:t('برنامج آخر','Other program')}[u.program])}</dd></dl><p class="tiny muted">${t('البريد وسيلة تواصل للحساب، وليس إثباتًا لهوية طالب جامعي. لا يتم إرسال بريد تلقائي حاليًا.','Email identifies the account; it is not verified university enrollment. No automated email is currently sent.')}</p><a class="btn soft mt" href="#/progress">${i('chart')}${t('عرض تقدمي ومزامنته','View progress & sync')}</a></section><section class="card pad"><h2>${t('الأمان','Security')}</h2><p class="small">${t('كلمة المرور مشفرة بتجزئة آمنة. تغيير كلمة المرور ينهي الجلسات القديمة. احتفظ برمز الاستعادة في مكان آمن.','Passwords are securely hashed. Changing your password ends old sessions. Keep your recovery code somewhere safe.')}</p>${!u.must_change?passwordForm('student-password-form'):''}<div class="divider"></div><button class="btn soft" data-action="recovery-rotate">${i('key')}${t('إصدار رمز استعادة جديد','Generate new recovery code')}</button><p class="tiny muted mt">${t('استخدمه إذا نسيت كلمة المرور. الرمز الجديد يلغي القديم.','Use it if you forget your password. A new code invalidates the old one.')}</p></section></div>${footer()}`;}
function syncPanel(){return S.student?`<div class="info-box ${S.syncState==='conflict'?'warning':'neutral'} mb"><strong>${h(syncLabel())}</strong><p class="small">${t('الملاحظات والتقدم خاصة بحسابك. تُحفظ نسخة على الجهاز وأخرى على الخادم عند الاتصال.','Notes and progress are private to your account, with a device copy and a server copy when connected.')}</p>${S.syncState==='conflict'?`<button class="btn sm" data-action="sync-load">${t('تحميل أحدث نسخة من الخادم','Load latest server copy')}</button>`:S.syncState==='error'?`<button class="btn sm" data-action="sync-retry">${t('إعادة المزامنة','Retry sync')}</button>`:''}</div>`:'';}
function officialLinks(s=null){const url='https://lms.ksiu.edu.eg/login/index.php';const code=s?.code||'';return `<section class="card pad"><span class="badge green">${t('روابط رسمية','Official links')}</span><h2>${t('بوابة الجامعة للتعلّم','University learning portal')}</h2><p>${t('افتح LMS بحساب الجامعة للوصول إلى مقرراتك، التكليفات، الكويزات والاختبارات المنشورة داخل كل مقرر. هذه المنصة لا تسحب درجاتك أو مواعيدك من الجامعة.','Open the LMS with your university account for your enrolled courses, assignments, quizzes and exams. This platform does not import your university grades or deadlines.')}</p>${s?`<div class="info-box neutral">${t('ابحث داخل LMS عن رمز المادة:','Search inside the LMS for course code:')} <strong class="en">${h(s.code)}</strong></div>`:''}<div class="flex wrap mt"><a class="btn primary" href="${url}" target="_blank" rel="noopener noreferrer">${i('external')}${t('فتح LMS الرسمي','Open official LMS')}</a><a class="btn" href="${UNIVERSITY_URL}" target="_blank" rel="noopener noreferrer">${t('صفحة الهندسة الرسمية','Official engineering page')}</a></div><div class="divider"></div><h3>${t('تستطيع داخل LMS','Inside the LMS')}</h3><ul class="security-list"><li>${t('التكليفات وتسليم الواجبات حسب كل مقرر','Assignments and submissions for each enrolled course')}</li><li>${t('الكويزات والاختبارات التي يفعّلها عضو التدريس','Quizzes and exams enabled by the instructor')}</li><li>${t('ملفات المحاضرات والإعلانات والدرجات المنشورة','Lecture files, announcements and published grades')}</li></ul><p class="tiny muted mt">${t('التكليفات والاختبارات ومواعيدها يحددها الدكتور داخل LMS. لم نتمكن من التحقق من صفحات المقررات المحمية أثناء إعداد الموقع؛ لا تعرض المنصة مواعيد مختلقة.','Instructors define assignments, exams and deadlines inside the LMS. Protected course pages could not be verified during setup; no deadlines are invented here.')}</p></section>`;}
const UNIVERSITY_URL='https://ksiu.edu.eg/el-tur/engineering-sciences/';
const PROGRAM_URL='https://ksiu.edu.eg/el-tur/engineering-sciences/mechatronics/';
function universityPage(){return `${heading(t('دليل الجامعة','University guide'),t('معلومات موثقة من صفحات جامعة الملك سلمان الدولية — فرع الطور.','Verified information from King Salman International University, El Tur.'))}${officialLinks()}<div class="settings-grid mt"><section class="card pad"><div class="eyebrow">KSIU · EL TUR</div><h2>${t('مجال الهندسة','Field of Engineering')}</h2><p>${t('تسعى الكلية لتوفير بيئة تعليم مميزة للطلاب وأعضاء التدريس، وإعداد مهندس يتفاعل مع احتياجات المجتمع والعمل ويواكب التغيرات العلمية والتكنولوجية.','The faculty aims to provide a distinctive learning environment and prepare engineers who respond to society and work, keeping pace with scientific and technological change.')}</p><h3>${t('قيم تذكرها الصفحة الرسمية','Values listed on the official page')}</h3><div class="chips">${[['المسؤولية','Responsibility'],['الشفافية','Transparency'],['الجودة','Quality'],['العمل الجماعي','Teamwork'],['التطوير الذاتي','Self-development'],['الاستدامة','Sustainability']].map(x=>`<span class="chip">${t(...x)}</span>`).join('')}</div><a class="text-link mt" href="${UNIVERSITY_URL}" target="_blank" rel="noopener noreferrer">${t('المصدر الرسمي','Official source')}${i('external')}</a></section><section class="card pad"><h2>${t('برنامج الميكاترونكس','Mechatronics Program')}</h2><p>${t('يدرس الميكاترونكس وتطبيقاته في الأتمتة الصناعية والسيارات والأنظمة الميكاترونية الدقيقة والحيوية. تذكر الصفحة الرسمية 10 فصول و166 ساعة معتمدة، ولغة الدراسة الإنجليزية.','Studies mechatronics and applications in industrial automation, cars, nano-mechatronics and biomechanics. The official page lists 10 semesters, 166 credit hours, and English as the language of study.')}</p><div class="info-box neutral">${t('تختلف الخطط بين البرامج. التقسيم هنا مرجعه خطة الميكاترونكس المنشورة؛ راجع برنامجك المعتمد قبل التسجيل.','Plans differ by program. This grouping follows the published Mechatronics plan; check your approved program before registration.')}</div><a class="btn soft mt" href="${PROGRAM_URL}" target="_blank" rel="noopener noreferrer">${t('الخطة والمصدر الرسمي','Official curriculum & source')}${i('external')}</a></section></div><section class="mt"><div class="section-head"><h2>${t('الفصل الأول','Semester 1')}</h2><span class="badge">${t('خطة الميكاترونكس','Mechatronics plan')}</span></div><div class="subject-grid">${semesterSubjects(1).map(subjectCard).join('')}</div></section><section class="mt"><div class="section-head"><h2>${t('الفصل الثاني','Semester 2')}</h2></div><div class="subject-grid">${semesterSubjects(2).map(subjectCard).join('')}</div></section><div class="info-box neutral mt">${t('توحيد الفيزياء: بناءً على توجيهك، كل محاضرات الفيزياء — بما فيها ملفات PHY212 المرفوعة — ضمن PHY111 بالفصل الأول، ولا توجد مادة فيزياء منفصلة بالفصل الثاني. تصحيح الرموز: الاستاتيكا MAT121، الديناميكا MAT122. UC0 مذكور في الخطة لكنه بلا ساعات معتمدة في الجدول، ولم نُدرجه كمادة إضافية مختلقة.','Physics is unified: per your direction, all physics lectures — including the uploaded PHY212 files — sit under PHY111 in Semester 1, with no separate semester-two physics subject. Code clarification: Statics is MAT121; Dynamics is MAT122. UC0 appears with zero credit hours and is not invented as an extra course.')}</div><section class="card pad mt"><h2>${t('خدمات تطوير المهارة','Career and skills development')}</h2><p>${t('تذكر صفحة الهندسة خدمات مراجعة السيرة الذاتية، والمقابلات التجريبية، والتطوير المهني، ومهارات العرض والعمل الجماعي والتواصل والقيادة. راجع الجامعة لمعرفة الفعاليات المتاحة حاليًا.','The engineering page lists résumé critique, mock interviews, career development, presentation, teamwork, communication and leadership skills. Check with the university for current availability.')}</p></section>${footer()}`;}

function passwordForm(id){return `<form id="${id}"><div class="field"><label for="${id}-current">${t('كلمة المرور الحالية','Current password')}</label><input id="${id}-current" type="password" name="current_password" autocomplete="current-password" maxlength="256" required></div><div class="field"><label for="${id}-new">${t('كلمة المرور الجديدة','New password')}</label><input id="${id}-new" type="password" name="new_password" autocomplete="new-password" minlength="12" maxlength="256" required></div><div class="field"><label for="${id}-confirm">${t('تأكيد كلمة المرور الجديدة','Confirm new password')}</label><input id="${id}-confirm" type="password" name="confirm_password" autocomplete="new-password" minlength="12" maxlength="256" required></div><button type="submit" class="btn primary">${i('lock')}${t('حفظ كلمة المرور','Save password')}</button></form>`;}
function showRecovery(code){openDialog(t('رمز الاستعادة — احفظه الآن','Recovery code — save it now'),`<div class="info-box warning">${t('هذا الرمز يظهر مرة واحدة. احفظه في مكان آمن؛ ستحتاجه إذا نسيت كلمة المرور. لا تشاركه مع أحد.','This code is shown once. Save it safely; you will need it if you forget your password. Never share it.')}</div><div class="recovery-code en" dir="ltr">${h(code)}</div><div class="dialog-foot"><button class="btn primary" data-action="copy-recovery" data-code="${h(code)}">${i('copy')}${t('نسخ الرمز','Copy code')}</button><button class="btn" data-action="close-dialog">${t('حفظته','I saved it')}</button></div>`);}
function recoverPage(){return `${heading(t('استعادة الحساب','Account recovery'),t('استخدم رمز الاستعادة الذي حفظته عند إنشاء الحساب أو من صفحة حسابك.','Use the recovery code saved when you created your account or from your account page.'))}<section class="card auth-card narrow"><form id="recover-form"><div class="field"><label for="rec-user">${t('اسم المستخدم أو البريد','Username or email')}</label><input id="rec-user" name="username" autocomplete="username" maxlength="254" dir="ltr" required></div><div class="field"><label for="rec-code">${t('رمز الاستعادة','Recovery code')}</label><input id="rec-code" name="recovery_code" autocomplete="off" maxlength="128" dir="ltr" required></div><div class="field"><label for="rec-pass">${t('كلمة المرور الجديدة','New password')}</label><input id="rec-pass" name="new_password" type="password" autocomplete="new-password" minlength="12" maxlength="256" dir="ltr" required></div><button class="btn primary full" type="submit">${i('key')}${t('تعيين كلمة مرور جديدة','Set new password')}</button></form><a class="text-link mt" href="#/login">${t('العودة لتسجيل الدخول','Back to sign in')}</a></section>${footer()}`;}
async function recoverAccount(form){const data=Object.fromEntries(new FormData(form));const r=await api('/api/student/recover',{method:'POST',body:data});showRecovery(r.recovery_code);toast(t('تم تغيير كلمة المرور. سجّل الدخول بها.','Password changed. Sign in with it.'));navigate('#/login');}
function md(text){if(typeof marked==='undefined')return `<p>${h(text).replace(/\n/g,'<br>')}</p>`;return DOMPurify.sanitize(marked.parse(String(text||''),{breaks:true,gfm:true}),{ALLOWED_TAGS:['p','br','strong','em','code','pre','ul','ol','li','blockquote','h1','h2','h3','h4','table','thead','tbody','tr','th','td','a','hr'],ALLOWED_ATTR:['href','title','class'],ALLOW_DATA_ATTR:false});}
async function assistantPage(){
 if(OFFLINE)return `${heading(t('مساعد Claude','Claude AI'))}<div class="ai-offline card">${i('spark')}<h2>${t('المساعد يحتاج اتصالًا بالخادم','The assistant needs the server')}</h2><p>${t('النسخة المستقلة تتيح المحتوى والتدريب دون إنترنت. مساعد Claude الحقيقي يعمل في نسخة الخادم بعد تفعيل مفتاح Anthropic API.','The standalone edition supports offline study and practice. Real Claude works in the server edition after an Anthropic API key is configured.')}</p><a class="btn primary" href="#/practice">${t('ابدأ تدريبًا','Start practice')}</a></div>${footer()}`;
 if(!S.student)return `${heading(t('مساعد Claude','Claude AI'),t('ذكاء اصطناعي حقيقي للدراسة والأسئلة العامة.','Real AI for study and general questions.'))}<div class="ai-gate card">${i('spark')}<h2>${t('سجّل الدخول لبدء المحادثة','Sign in to start chatting')}</h2><p>${t('المحادثات خاصة بحسابك. نحدّ الاستخدام اليومي لحماية الخدمة ومنع إساءة الاستخدام.','Conversations are private to your account. Daily limits protect the service from abuse.')}</p><div class="flex wrap"><a class="btn primary" href="#/login">${t('تسجيل الدخول','Sign in')}</a><a class="btn" href="#/register">${t('حساب جديد','Create account')}</a></div></div>${footer()}`;
 try{const [status,conv]=await Promise.all([api('/api/ai/status'),api('/api/ai/conversations')]);S.ai.status=status;S.ai.conversations=conv.items;if(!S.ai.active&&conv.items.length)S.ai.active=conv.items[0].id;if(S.ai.active){const m=await api('/api/ai/conversations/'+encodeURIComponent(S.ai.active)+'/messages');S.ai.messages=m.items;}}catch(e){S.ai.status={configured:false,error:e.message};}
 const a=S.ai;return `${heading(t('مساعد Claude','Claude AI'),t('اسأل عن أي موضوع: دراسة، برمجة، لغات، أو فضول عام.','Ask about anything: study, programming, languages, or general curiosity.'))}<div class="ai-layout"><aside class="ai-sidebar card"><button class="btn primary full" data-action="ai-new">${i('plus')}${t('محادثة جديدة','New chat')}</button><div class="ai-conversations">${a.conversations.map(c=>`<div class="ai-conv ${c.id===a.active?'active':''}"><button class="ai-conv-open" data-action="ai-open" data-id="${h(c.id)}">${h(c.title)}</button><button class="icon-btn bare" data-action="ai-delete" data-id="${h(c.id)}" aria-label="${t('حذف المحادثة','Delete conversation')}">${i('trash')}</button></div>`).join('')||`<p class="tiny muted">${t('لا توجد محادثات بعد.','No conversations yet.')}</p>`}</div><div class="ai-quota tiny muted">${a.status?.configured?`${t('اليوم','Today')}: ${fmt(a.status.used_today||0)} / ${fmt(a.status.daily_limit||40)}`:''}</div></aside><section class="ai-chat card"><div class="ai-chat-head"><span class="ai-avatar">${i('spark')}</span><div><strong>Claude</strong><span class="tiny muted">${a.status?.configured?h(a.status.model||''):t('غير مفعّل بعد','Not configured yet')}</span></div>${a.busy?`<button class="btn sm" data-action="ai-stop">${t('إيقاف','Stop')}</button>`:''}</div><div class="ai-messages" id="ai-messages">${!a.status?.configured?`<div class="info-box warning">${h(a.status?.error||t('مساعد Claude غير مفعّل بعد. يحتاج الموقع إلى مفتاح Anthropic API على الخادم. لن نخترع إجابات أو ندّعي أن المساعد يعمل.','Claude is not configured yet. The site needs an Anthropic API key on the server. We will not fake answers or pretend the assistant is working.'))}</div>`:''}${a.messages.map(m=>aiMessage(m.role,m.content)).join('')}${!a.messages.length&&a.status?.configured?`<div class="ai-welcome"><h2>${t('بماذا أساعدك اليوم؟','How can I help today?')}</h2><div class="ai-prompts">${[['اشرح لي قانون نيوتن الثاني بمثال','Explain Newton’s second law with an example'],['ساعدني أذاكر للاستاتيكا','Help me study Statics'],['اكتب دالة بايثون تعكس نصًا','Write a Python function that reverses a string'],['ما الفرق بين AC و DC؟','What is the difference between AC and DC?']].map(x=>`<button class="chip" data-action="ai-prompt" data-value="${h(t(...x))}">${h(t(...x))}</button>`).join('')}</div></div>`:''}</div><form id="ai-form" class="ai-form"><textarea id="ai-input" name="message" rows="2" maxlength="6000" placeholder="${t('اكتب سؤالك هنا…','Type your question…')}" ${!a.status?.configured||a.busy?'disabled':''} required></textarea><button class="btn primary" type="submit" ${!a.status?.configured||a.busy?'disabled':''}>${i('send')}${t('إرسال','Send')}</button></form><p class="tiny muted ai-privacy">${t('تُرسل رسائلك إلى Claude. قد يخطئ؛ راجع المعلومات المهمة. لا تشارك كلمات المرور أو البيانات السرية.','Messages are sent to Claude. It can make mistakes; verify important information. Never share passwords or sensitive data.')}</p></section></div>${footer()}`;
}
function aiMessage(role,content){return `<div class="ai-message ${role}"><div class="ai-bubble">${role==='assistant'?md(content):`<p>${h(content).replace(/\n/g,'<br>')}</p>`}${role==='assistant'&&content?`<button class="icon-btn bare ai-copy" data-action="ai-copy" aria-label="${t('نسخ الرد','Copy reply')}">${i('copy')}</button>`:''}</div></div>`;}
function aiScroll(){const box=$('#ai-messages');if(box)box.scrollTop=box.scrollHeight;}
async function sendAI(){const input=$('#ai-input');if(!input||S.ai.busy)return;const text=input.value.trim();if(!text)return;S.ai.busy=true;S.ai.messages.push({role:'user',content:text});input.value='';const box=$('#ai-messages');if(box){box.insertAdjacentHTML('beforeend',aiMessage('user',text));box.insertAdjacentHTML('beforeend',`<div class="ai-message assistant" id="ai-stream"><div class="ai-bubble"><span class="typing"><span></span><span></span><span></span></span></div></div>`);aiScroll();}
 const controller=new AbortController();S.ai.controller=controller;let answer='';
 try{const response=await fetch('/api/ai/chat',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Method-CSRF':S.studentCsrf},body:JSON.stringify({conversation_id:S.ai.active,message:text}),signal:controller.signal});if(!response.ok){const d=await response.json().catch(()=>({}));throw new Error(d.detail||t('تعذّر إرسال الرسالة.','Could not send message.'));}
  const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';const stream=$('#ai-stream .ai-bubble');
  while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let idx;while((idx=buffer.indexOf('\n\n'))>=0){const raw=buffer.slice(0,idx);buffer=buffer.slice(idx+2);let event='message',data='';for(const line of raw.split('\n')){if(line.startsWith('event:'))event=line.slice(6).trim();if(line.startsWith('data:'))data+=line.slice(5).trim();}if(!data)continue;const obj=JSON.parse(data);if(event==='start'){S.ai.active=obj.conversation_id;}else if(event==='delta'){answer+=obj.text;if(stream){stream.innerHTML=md(answer);aiScroll();}}else if(event==='error'){throw new Error(obj.detail||t('انقطع الرد.','Reply interrupted.'));}else if(event==='done'){S.ai.active=obj.conversation_id;}}}
  if(!answer)throw new Error(t('لم يصل رد. حاول مجددًا.','No reply received. Try again.'));S.ai.messages.push({role:'assistant',content:answer});
 }catch(e){if(e.name!=='AbortError'){toast(e.message,'error');S.ai.messages.push({role:'assistant',content:t('تعذّر إكمال الرد: ','Could not complete the reply: ')+e.message});}else if(answer){S.ai.messages.push({role:'assistant',content:answer});}}
 finally{S.ai.busy=false;S.ai.controller=null;await render();}
}

async function init(){
 document.title='ENG YOUSSEF | '+t('مساحتك للتعلّم','Your learning space');document.documentElement.lang=S.lang;document.documentElement.dir=S.lang==='ar'?'rtl':'ltr';
 try{const d=await api('/api/bootstrap');S.data={subjects:d.subjects,lectures:d.lectures,stats:d.stats,sources:d.sources||null,files:d.files||[]};S.university=d.university;S.student=d.student;S.studentCsrf=d.student_csrf||'';S.csrf=d.csrf;S.admin=false;S.mustChange=false;
 if(S.student){S.local=emptyLocal();if(!S.student.must_change)await loadStudentProgress();}else{S.local=loadLocal();}shell();if(!OFFLINE){try{const saved=JSON.parse(sessionStorage.getItem('method.activeQuiz')||'null');if(saved&&Array.isArray(saved.questions)&&saved.questions.length<=100&&saved.answers?.length===saved.questions.length&&saved.orders?.length===saved.questions.length&&getSubject(saved.subject_id)&&!saved.finished&&saved.questions.every(q=>typeof q.prompt==='string'&&Array.isArray(q.options)&&q.options.length>=2&&Number.isInteger(q.correct)&&q.correct<q.options.length)){S.quiz=saved;S.quiz.index=Math.max(0,Math.min(saved.questions.length-1,Number(saved.index)||0));if(saved.deadline&&saved.deadline<Date.now())finishQuiz(true);}}catch{sessionStorage.removeItem('method.activeQuiz');}}
 await render();
 }catch(e){$('#app').innerHTML=`<div class="boot"><div class="boot-logo"><img src="assets/brand-mark.jpg" alt=""></div><h1>ENG YOUSSEF</h1><p>${h(e.message)}</p><button class="btn primary" id="boot-retry">${t('إعادة المحاولة','Try again')}</button></div>`;$('#boot-retry').addEventListener('click',init);}
}
init();
